export interface EncounterResult {
  readonly line: Line;
  readonly taskSlug: TaskSlug;
  readonly trials: readonly { correct: boolean }[];
  /** Optional: which drive the player's choices leaned toward. */
  readonly driveChoice?: Drive;
}

