  return QUADRANT_TO_DRIVE[LINE_QUADRANT[line]] ?? 'Agency';
}

const SIGNAL_TO_QUADRANT: Record<string, ShadowQuadrant> = {
  fixation: 'DarkAddiction',
  regression: 'DarkAllergy',
  repression: 'GoldenAddiction',
};

